// Fleet standing verdict.
// Matching is DELIBERATELY fuzzy-tolerant: boxName is free text an LLM fills in from
// a hint, and three different slug conventions exist across the fleet
// (openclaw-0ht9 / vps-widget-co / rescue-jane-doe). An exact box_slug
// match would return `unmatched` on drift, and unmatched PROCEEDS -- so the clients
// we want blocked would sail through. We therefore match on box_slug, every alias,
// and client_label.
const wh = $('Webhook — Fleet Standing Check').first().json;
const body = wh.body || wh;

const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const boxName    = norm(body.boxName);
const clientName = norm(body.clientName || body.client);
const agentName  = norm(body.agentName  || body.agent);
const action     = String(body.action || 'escalate');
const ticketId   = String(body.ticketId || '');

const now = new Date();
const day = now.toISOString().slice(0, 10);
const requested_at = now.toISOString();

const inputItems = $input.all();
const lookupErrored = inputItems.length > 0 && inputItems[0].json && inputItems[0].json.error;
const rows = lookupErrored ? [] : inputItems
  .map(i => i.json)
  .filter(r => r && typeof r === 'object' && Object.keys(r).length > 0 && r.box_slug);

// candidate identifiers supplied by the caller
const supplied = [boxName, clientName, agentName].filter(Boolean);

function rowMatches(r) {
  const keys = [];
  if (r.box_slug)     keys.push(norm(r.box_slug));
  if (r.client_label) keys.push(norm(r.client_label));
  if (r.aliases)      String(r.aliases).split('|').forEach(a => { const n = norm(a); if (n) keys.push(n); });
  return supplied.some(s => keys.includes(s));
}

let matched = rows.filter(rowMatches);

const MSG = "I'd normally escalate this to the Rescue Rangers team for you. Before I do — it looks like the account may not be current on payments, so let me confirm with management before I put the request in. I'll come back to you as soon as I hear.";

let verdict = 'unmatched', reason = 'no_record_found', good_standing = false, client_message = MSG;
let matchedRow = null;

if (lookupErrored) {
  verdict = 'held'; reason = 'lookup_error';
} else if (supplied.length === 0) {
  verdict = 'unmatched'; reason = 'no_identifier_supplied';
} else if (matched.length === 0) {
  verdict = 'unmatched'; reason = 'no_record_found';
} else {
  // if ANY matched row is explicitly not in good standing, that wins -- a client with
  // two records must not slip through on the good one.
  const bad = matched.find(r => r.good_standing === false);
  matchedRow = bad || matched[0];
  if (bad) {
    verdict = 'blocked'; reason = 'good_standing_is_false';
  } else if (matchedRow.good_standing === true) {
    verdict = 'allowed'; reason = ''; good_standing = true; client_message = '';
  } else {
    verdict = 'unmatched'; reason = 'good_standing_null_or_not_boolean';
  }
}

const responseBody = { ok: verdict === 'allowed', good_standing, verdict, reason, client_message };

const ledgerRow = {
  ticket_id: ticketId,
  box_slug: (matchedRow && matchedRow.box_slug) || boxName || clientName || '',
  client_label: (matchedRow && matchedRow.client_label) || '',
  agent_name: (matchedRow && matchedRow.agent_name) || agentName || '',
  action,
  verdict,
  reason,
  day_key: ((matchedRow && matchedRow.box_slug) || boxName || clientName || 'unknown') + '|' + day,
  requested_at,
};

return [{ json: { responseBody, ledgerRow } }];
